    h9 += carry8;
    h8 = (int64_t) ((uint64_t) h8 - (uint64_t) carry8 * ((uint64_t) 1L << 26));

    carry9 = (h9 + (int64_t)(1L << 24)) >> 25;
    h0 += carry9 * 19;
    h9 = (int64_t) ((uint64_t) h9 - (uint64_t) carry9 * ((uint64_t) 1L << 25));

    carry0 = (h0 + (int64_t)(1L << 25)) >> 26;
